CREATE OR REPLACE FUNCTION public.crm_import_restore_lead_links() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF auth.uid() IS DISTINCT FROM '6ca0eff8-7393-47bc-9054-9001138bcbc2'::uuid OR NOT public.is_erp_admin(auth.uid()) OR NOT private.has_app_access(auth.uid(),'crm') THEN RAISE EXCEPTION 'Importação não autorizada'; END IF; PERFORM set_config('app.crm_history_import','20261117',true); IF NOT public.crm_history_import_active() THEN RAISE EXCEPTION 'Importação encerrada'; END IF; UPDATE public.crm_leads l SET oportunidade_id=(o.payload->>'oportunidade_id')::uuid FROM public.crm_import_originals o WHERE o.run_id='20261117' AND o.table_name='leads' AND l.id=(o.payload->>'id')::uuid AND o.payload->>'oportunidade_id' IS NOT NULL AND EXISTS(SELECT 1 FROM public.crm_oportunidades p WHERE p.id=(o.payload->>'oportunidade_id')::uuid); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.crm_import_restore_lead_links() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_import_restore_lead_links() TO authenticated;